"use strict";
// A CommonJS package compiled natively. It keeps the island package's
// exported function in a `var` and calls it while the module evaluates.
var measure = require("measure-table");

var cupToMl = measure("cup");

exports.scale = function scale(name, amount) {
  var convert = measure(name, true);
  if (typeof convert !== "function") return -1;
  return convert(amount) + cupToMl(0);
};
